import{_ as e,o as s,c as i,a5 as r}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"3DCGの形と見た目から読む","description":"","frontmatter":{"title":"3DCGの形と見た目から読む","study":{"source":"新規執筆","section":"learning","format":"path","status":"published","domain":"graphics","collection":"foundations","order":4,"summary":"メッシュ、座標とカメラ、材質と光、アニメーション、リグとスキニングを図で確かめる読み順。"}},"headers":[],"relativePath":"guide/graphics-basics.md","filePath":"guide/graphics-basics.md"}'),t={name:"guide/graphics-basics.md"};function h(l,a,d,n,o,c){return s(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="_3dcgの形と見た目から読む" tabindex="-1">3DCGの形と見た目から読む <a class="header-anchor" href="#_3dcgの形と見た目から読む" aria-label="Permalink to &quot;3DCGの形と見た目から読む&quot;">​</a></h1><p>モデルを置いたりマテリアルを設定したりすると、画像にどう反映されるかを調べます。形、位置、見た目、画像を作る処理の順に確認します。</p><h2 id="読む順番" tabindex="-1">読む順番 <a class="header-anchor" href="#読む順番" aria-label="Permalink to &quot;読む順番&quot;">​</a></h2><ol><li><a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a>で、頂点や面がどのように形を表すかを調べます。</li><li><a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a>で、物体の位置と、画面からの見え方を追います。</li><li><a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a>で、形の表面にどんな情報を与えるかを見ます。</li><li><a href="/study/graphics/basics/light-and-rendered-images.html">光と描画された画像</a>で、シーンから画像を作る流れをつなげます。</li></ol><h2 id="形を時間に合わせて動かす" tabindex="-1">形を時間に合わせて動かす <a class="header-anchor" href="#形を時間に合わせて動かす" aria-label="Permalink to &quot;形を時間に合わせて動かす&quot;">​</a></h2><ol><li><a href="/study/graphics/basics/keyframes-and-animation.html">キーフレームとアニメーション</a>で、時間に沿って位置や値を変える仕組みを見ます。</li><li><a href="/study/graphics/basics/rigs-and-skinning.html">リグとスキニング</a>で、骨の配置とメッシュの変形をつなげます。</li></ol><h2 id="シェーダーのコードから描く" tabindex="-1">シェーダーのコードから描く <a class="header-anchor" href="#シェーダーのコードから描く" aria-label="Permalink to &quot;シェーダーのコードから描く&quot;">​</a></h2><ol><li><a href="/study/graphics/shader/shader-first-steps.html">シェーダーの第一歩</a>で、頂点の処理、補間、色の計算を追います。</li><li><a href="/study/graphics/shader/shader-inputs-and-uniforms.html">シェーダーへ渡すデータ</a>で、属性やuniform、バッファと参照の役割を見ます。</li><li><a href="/study/practice/graphics/shader-first-steps.html">三角形のシェーダー実践</a>で、色と位置を操作し、GLSLとHLSLの対応を読みます。</li></ol><h2 id="図から確かめること" tabindex="-1">図から確かめること <a class="header-anchor" href="#図から確かめること" aria-label="Permalink to &quot;図から確かめること&quot;">​</a></h2><ul><li>同じ形でも、位置、カメラ、材質、光が変わると見え方が変わる理由を説明できる。</li><li>頂点やUV、テクスチャなどのデータと、それを使う計算の役割を区別できる。</li><li>ゲーム内の配置から、画面に表示する画像が作られるまでの段階をたどれる。</li></ul><h2 id="さらに調べる" tabindex="-1">さらに調べる <a class="header-anchor" href="#さらに調べる" aria-label="Permalink to &quot;さらに調べる&quot;">​</a></h2><p>数学から確認したいときは<a href="/study/math/rendering/vector.html">ベクトル</a>、<a href="/study/math/rendering/transform.html">座標変換</a>、<a href="/study/math/rendering/camera.html">カメラ</a>へ進みます。GPUでの処理を追う場合は<a href="/study/graphics/pipeline/overview.html">レンダリングパイプライン</a>、制作したモデルの取り込みは<a href="/study/graphics/mesh/mesh-import-and-cooking.html">メッシュのインポート</a>が次の入口です。</p><p>ゲームを組み立てる側の基礎は、<a href="/study/guide/game-development-basics.html">ゲームの動きと構成から読む</a>へ進めます。</p>',13)])])}const p=e(t,[["render",h]]);export{u as __pageData,p as default};
